// Research-only biomedical starter knowledge for Cloudbite roles 111-120 (Falsify research expert extension).
// Every card is original synthesis written for Cloudbite; no source text is quoted or mirrored.
// Evaluation status is unvalidated: these packs are source-linked starter knowledge, not validated professional expertise.
// Source checkStatus is 'retrieved' only when the document was actually read during authoring (checkedAt is that UTC time).
// Scope is document, evidence and benchmark review. Nothing here is diagnosis, treatment, dosing, or wet-lab/synthesis instruction.
import type { PhaseOneKnowledgePack } from './cloudbite-phase-one-data';

type Source = PhaseOneKnowledgePack['sources'][number];
type Card = PhaseOneKnowledgePack['cards'][number];
type CardDraft = Omit<Card, 'roles' | 'provenance'>;
type Check = Pick<Source, 'checkedAt' | 'checkStatus' | 'checkNote'>;

